import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
       BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
       StringTokenizer st;
       Random rnd=new Random();
       int t=Integer.parseInt(br.readLine());
       while(t-->0){
           int n=Integer.parseInt(br.readLine());
           int le=3*n;
           long[] arr=new long[le];
           String sv=br.readLine();
           st=new StringTokenizer(sv);
           for(int i=0;i<le;i++){
               arr[i]=Long.parseLong(st.nextToken());
           }
           
           for(int i=0;i<le;i++){
               int j=rnd.nextInt(i+1);
               long temp=arr[i];
               arr[i]=arr[j];
               arr[j]=temp;
           }
           Arrays.sort(arr);
           long[] p=new long[le+1];
           for(int i=0;i<le;i++){
               p[i+1]=p[i]+arr[le-1-i];
           }
           long max=-1;
           for(int s=0;s<=n;s++){
               int l=0;
               int r=s;
               while(r-l>2){
                   int m1=l+(r-l)/3;
                   int m2=r-(r-l)/3;
                   long f1=p[n-s+2*m1]+3L*p[n+2*s-m1];
                   long f2=p[n-s+2*m2]+3L*p[n+2*s-m2];
                   if(f1<f2){
                       l=m1;
                   }
                   else if(f1>f2){
                       r=m2;
                   }
                   else{
                       l=m1;
                       r=m2;
                   }
               }
               for(int v=l;v<=r;v++){
                   long ans=2L*p[n-s]+p[n-s+2*v]+3L*p[n+2*s-v];
                   if(ans>max){
                       max=ans;
                   }
               }
           }
           System.out.println(max);
       }
	}
}
